import { BUTTON_PAD } from '../surface'

/** A path as the pane shows it outside the project: from `~/` where it sits under the home folder, whole otherwise. */
export function shortPath(path: string, home: string | null): string {
  const base = home?.replace(/\/$/, '') ?? null
  return base !== null && path.startsWith(`${base}/`) ? `~/${path.slice(base.length + 1)}` : path
}

/** The folder a file sits in, as the File view names it: from `~` where it is under the home folder, whole otherwise. The home folder itself is `~`. */
export const locationOf = (dir: string, home: string | null): string =>
  home !== null && dir === home.replace(/\/$/, '') ? '~' : shortPath(dir, home)

/** The characters of a cut path's start kept at least when its file name is cut too. */
const MIN_START = 8

/** The fewest letters of a cut folder's name worth showing before its …. */
const MIN_PARTIAL = 2

/** A path split for cutting: the folders before its file name (the first is '' on an absolute path), and the file name with its slash. */
type Split = { folders: string[]; file: string }

/** The path with `head` folders from its start, `tail` from its end, and `cutFolder` standing for the ones between. */
const joined = ({ folders, file }: Split, head: number, tail: number, cutFolder = '…'): string =>
  `${[...folders.slice(0, head), cutFolder, ...folders.slice(folders.length - tail)].join('/')}${file}`

/** How many folders to keep at the start and at the end: the end's nearest the file first, then the start's, as long as the room holds. */
function foldersKept(path: Split, room: number): [number, number] {
  let head = 1
  let tail = 0
  for (let isGrowing = true; isGrowing;) {
    isGrowing = false
    for (const isTail of [true, false]) {
      const [nextHead, nextTail] = isTail ? [head, tail + 1] : [head + 1, tail]
      if (nextHead + nextTail < path.folders.length && joined(path, nextHead, nextTail).length <= room) {
        ;[head, tail] = [nextHead, nextTail]
        isGrowing = true
      }
    }
  }
  return [head, tail]
}

/**
 * The path with the folders in its middle swapped for `…`, its first folder and its whole file name kept, and as many
 * whole folders either side as fit: `/private/tmp/…/notes/ab-03.md`. Room left over shows the start of the first folder
 * cut, `/private/tmp/cl…/notes/ab-03.md`. Where even `/…/ab-03.md` does not fit it is `…/ab-03.md`; null where that
 * does not fit either, or the path has no folder to cut.
 */
function cutFolders(text: string, room: number): string | null {
  const slash = text.lastIndexOf('/')
  if (slash < 0) return null
  const path = { folders: text.slice(0, slash).split('/'), file: text.slice(slash) }
  if (path.folders.length < 2 || joined(path, 1, 0).length > room)
    return `…${path.file}`.length <= room ? `…${path.file}` : null
  const [head, tail] = foldersKept(path, room)
  const spare = room - joined(path, head, tail).length
  if (spare < MIN_PARTIAL) return joined(path, head, tail)
  return joined(path, head, tail, `${path.folders[head]?.slice(0, spare) ?? ''}…`)
}

/** The text cut to `room` characters with a … at its end; whole where it fits. */
export function endCut(text: string, room: number): string {
  if (text.length <= room) return text
  if (room < 2) return room < 1 ? '' : '…'
  return `${text.slice(0, room - 1)}…`
}

/**
 * The text cut to `room` characters with a … in the middle. A path keeps its first folder and its whole file name and
 * loses the folders between, cut at a slash. Where even that does not fit, or the text has no folders, start and end
 * share the room, the start at least MIN_START characters where the room allows.
 */
export function middleCut(text: string, room: number): string {
  if (text.length <= room) return text
  if (room < 2) return room < 1 ? '' : '…'
  const folders = cutFolders(text, room)
  if (folders !== null) return folders
  const keep = room - 1
  const name = text.length - text.lastIndexOf('/')
  const end = Math.max(Math.ceil(keep / 2), Math.min(name, keep - MIN_START))
  return `${text.slice(0, keep - end)}…${text.slice(text.length - end)}`
}

/** The fewest characters a cut name gets, however narrow the pane. A name given more than the row has left spills out of its column, so this is small. */
const LEAST_ROOM = 4

/** What sits in a file row beside its name button. */
type RowShape = { depth: number; tag: string | null; isRecent: boolean; countCells: readonly [number, number] }

/** The cells before the name: the marker, the chevron cell and the icon cell, one cell apart. */
const BEFORE_NAME = 1 + 1 + 2 + 1 + 2 + 1

/** The cells after the Tag and dot besides the two count columns: a gap, the spacer, and the gap between the columns. */
const COUNTS_GAPS = 1 + 1 + 1

/**
 * How many characters a file row's name button may hold in a pane `columns` cells wide. A row draws, one cell apart:
 * the indent (2 per level), the marker, the chevron cell, the icon cell, the button, the Tag, the dot and the counts (`countCells`, the width of each of the two columns as the row draws them).
 * The desktop app draws the button wider than its label (BUTTON_PAD) and cuts a label that does not fit at its end,
 * so the mod cuts it first.
 */
export function nameRoom(columns: number, row: RowShape): number {
  if (columns <= 0) return Infinity
  const tag = row.tag === null ? 0 : 1 + row.tag.length
  const dot = row.isRecent ? 2 : 0
  const counts = COUNTS_GAPS + row.countCells[0] + row.countCells[1]
  return Math.max(columns - row.depth * 2 - BEFORE_NAME - tag - dot - counts - BUTTON_PAD, LEAST_ROOM)
}

/** The cells a Group heading draws beside its place: the marker, the chevron cell, the name, the count and the five gaps between its six parts. The name is a Button on the desktop, which draws it wider than its label. */
const GROUP_CELLS = 1 + 2 + BUTTON_PAD + 5

/** How many characters a Group heading's place may hold in a pane `columns` cells wide, after its name and its count; unlimited where the pane reports no width. */
export function placeRoom(columns: number, name: string, count: number): number {
  return columns <= 0 ? Infinity : columns - GROUP_CELLS - name.length - String(count).length
}

/**
 * How many characters a folder row's label may hold in a pane `columns` cells wide, `levels` tree levels down. The
 * desktop row draws, one cell apart: the marker, the chevron cell, the folder icon and the name button, which the app
 * draws wider than its label (BUTTON_PAD). The terminal's has no icon and a one-cell chevron, and its label ends in a slash.
 */
export function folderRoom(columns: number, levels: number, isDesktop: boolean): number {
  if (columns <= 0) return Infinity
  const before = isDesktop ? 1 + 1 + 2 + 1 + 2 + 1 + BUTTON_PAD : 1 + 1 + 1 + 1
  return Math.max(columns - levels * 2 - before, LEAST_ROOM)
}

/**
 * How many characters of a line the acting form's row may hold in a pane `columns` cells wide, after its number (`numberWidth`
 * digits) and the two spaces behind it. The desktop app draws a Button wider than its label (BUTTON_PAD) and cuts
 * a label that does not fit at its end, so the mod cuts it first.
 */
export function lineRoom(columns: number, numberWidth: number, isDesktop: boolean): number {
  if (columns <= 0) return Infinity
  return Math.max(columns - numberWidth - 2 - (isDesktop ? BUTTON_PAD : 0), LEAST_ROOM)
}

files.hooks/tracer/reveal.ts:
// Reveal: from the operating system and a path to the button's label and the command that opens the file manager.

/** The systems Reveal knows: a Mac, Linux, or anything else, which reads as Windows. */
type System = 'Darwin' | 'Linux' | 'Windows'

/** What Reveal needs to know of the selection. */
export type RevealInput = {
  system: System
  path: string
  isFolder: boolean
  stillExists: boolean
  /** The nearest folder above the path that is still on disk. */
  nearestFolder: string
}

/** The button's label and the program with its arguments. */
export type Reveal = { label: string; argv: string[] }

/** The folder a path sits in. */
export const parentOf = (path: string) => (path.lastIndexOf('/') <= 0 ? '/' : path.slice(0, path.lastIndexOf('/')))

export function reveal(from: RevealInput): Reveal {
  // A path that is gone cannot be selected: its nearest folder opens instead.
  const input = from.stillExists ? from : { ...from, path: from.nearestFolder, isFolder: true }
  if (input.system === 'Linux') {
    return { label: 'Open folder', argv: ['xdg-open', input.isFolder ? input.path : parentOf(input.path)] }
  }
  if (input.system === 'Windows') {
    const label = 'Show in File Explorer'
    return { label, argv: input.isFolder ? ['explorer', input.path] : ['explorer', `/select,${input.path}`] }
  }
  const label = 'Show in Finder'
  if (input.isFolder) return { label, argv: ['open', input.path] }
  return { label, argv: ['open', '-R', input.path] }
}

/** The system `uname -s` named: its answer, or null where it did not run. */
export function systemOf(ran: { exitCode: number; stdout: string } | null): System {
  const name = ran !== null && ran.exitCode === 0 ? ran.stdout.trim() : ''
  return name === 'Darwin' || name === 'Linux' ? name : 'Windows'
}

files.hooks/tracer/status.ts:
/** One changed file in git's status: its two-letter code, its path in the repository, and where it came from. */
export type StatusEntry = { code: string; path: string; oldPath: string | null }

/**
 * Reads the output of `git status --porcelain=v1 -z`: entries `XY path`, each ended by a NUL. A rename or a copy
 * is followed by one more field, the path it came from.
 */
export function parseStatus(out: string): StatusEntry[] {
  const fields = out.split('\0')
  const entries: StatusEntry[] = []
  for (let i = 0; i < fields.length; i += 1) {
    const field = fields[i] ?? ''
    if (field.length < 4) continue
    const code = field.slice(0, 2)
    const isRename = code.includes('R') || code.includes('C')
    // A path ending in `/` is a folder that holds another repository: no file, and git cannot hash it.
    if (field.endsWith('/')) continue
    entries.push({ code, path: field.slice(3), oldPath: isRename ? (fields[(i += 1)] ?? null) : null })
  }
  return entries
}

files.hooks/tracer/view.ts:
import type { RecordEntry } from '../../types'
import { unifiedDiff } from './diff'

/** What the view area shows for a file: its text, the diff of a change to it, or a line saying why not; lines in `leads`, where there are any, go above it. */
export type FileView = ({ text: string } | { diff: string } | { note: string }) & { leads?: string[] }

/** A text with its line endings made plain line breaks: the code view refuses a carriage return, and a Windows file has them. */
const plain = (text: string) => text.replace(/\r\n?/g, '\n')

/** Whether the text holds a control character other than a tab or a newline: the code view refuses such text, and a program or an image holds them. */
function hasControlCharacter(text: string): boolean {
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i)
    if ((code < 32 && code !== 9 && code !== 10) || code === 127) return true
  }
  return false
}

/** The line for a file that holds a program or an image. */
const NOT_TEXT = 'This file is not text, so it cannot be shown here.'

/** The line for a file whose read failed. */
const GONE = 'This file is gone or cannot be read.'

/** The view for what a read of the file gave: its text, or null where the read failed. */
export function viewOfRead(read: string | null): FileView {
  if (read === null) return { note: GONE }
  // A carriage return is a control character too; a line ending of Windows' is a plain line break here.
  const text = plain(read)
  if (hasControlCharacter(text)) return { note: NOT_TEXT }
  return text === '' ? { note: 'This file is empty.' } : { text }
}

/** How many changes a view shows: the hunks of its diff; none for a text or a note. */
export const hunksOf = (view: FileView): number =>
  'diff' in view ? view.diff.split('\n').filter((line) => line.startsWith('@@ ')).length : 0

/** A path as the view names it: relative to the project where it is inside it, else whole. */
export const named = (cwd: string, path: string) => {
  const root = cwd.endsWith('/') ? cwd : `${cwd}/`
  return path.startsWith(root) ? path.slice(root.length) : path
}

/** The line saying why a changed file has no baseline: it was too big to keep, or it is not known. */
const lackOf = (entry: Pick<RecordEntry, 'isBaselineTooBig'>) =>
  entry.isBaselineTooBig ? 'The text before the change was too big to keep.' : 'The text before the change is unknown.'

/** The view of a diff under the lines leading it; a line saying so where the diff holds no change, and a different one where the file has no text at all. */
const diffView = (leads: string[], diff: string, isEmpty: boolean): FileView => {
  if (diff !== '') return { leads, diff }
  return { leads, note: isEmpty ? 'This file is empty.' : 'Nothing changed.' }
}

/** The view for a changed file: the diff from its baseline to what a read of it gave, under a line naming where a moved file came from. */
export function viewOfChange(
  entry: Pick<RecordEntry, 'tag' | 'baseline' | 'isBaselineTooBig' | 'oldPath'>,
  read: string | null,
  where: { cwd: string; path: string },
): FileView {
  const moved =
    entry.oldPath === undefined
      ? []
      : [`Moved from ${named(where.cwd, entry.oldPath)} to ${named(where.cwd, where.path)}`]
  if (read === null) return { leads: moved, note: GONE }
  const [before, after] = [plain(entry.baseline ?? ''), plain(read)]
  if (entry.baseline !== null && (hasControlCharacter(before) || hasControlCharacter(after))) {
    return { leads: moved, note: NOT_TEXT }
  }
  if (entry.baseline !== null) return diffView(moved, unifiedDiff(before, after), after === '')
  // A deleted file has no text now to show beside the line.
  if (entry.tag === 'Deleted') return { note: lackOf(entry) }
  return { leads: [...moved, lackOf(entry)], ...viewOfRead(read) }
}

/** How many characters the engine counts for a string: its UTF-8 bytes, so the `─` of a terminal divider counts three. */
const countedChars = (text: string): number => {
  let n = 0
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i)
    n += code < 0x80 ? 1 : code < 0x800 ? 2 : 3
  }
  return n
}

/** The prop of each kind of element that holds words the engine counts: the label of a Button, the words of a picture, the source of code. A picture's own source is markup, not words, and does not count. A Box's `key` counts too (measured: a Box keyed with 1,000 characters adds 1,000; a Button, Svg or Text key adds none). */
const WORDS_PROP: Record<string, string> = { Button: 'label', Svg: 'alt', Code: 'source' }

/** The characters of a string, or none for any other value. */
const wordsIn = (value: unknown): number => (typeof value === 'string' ? countedChars(value) : 0)

/** The characters one element's own props take: its words prop, and for a Box its key. */
function ownChars(type: string | undefined, props: Record<string, unknown> | null | undefined): number {
  const words = type === undefined ? undefined : WORDS_PROP[type]
  return (words === undefined ? 0 : wordsIn(props?.[words])) + (type === 'Box' ? wordsIn(props?.key) : 0)
}

/** How many characters of the one drawing's limit a built tree of elements takes: the words in its Text and in the props above. Counted by walking the elements, since the drawing is cut off past the limit and nothing says how near it is. */
export function drawnChars(node: unknown): number {
  if (typeof node === 'string') return countedChars(node)
  if (typeof node === 'number') return String(node).length
  if (Array.isArray(node)) return node.reduce((sum: number, child) => sum + drawnChars(child), 0)
  if (typeof node !== 'object' || node === null) return 0
  const { type, props, children } = node as {
    type?: string
    props?: Record<string, unknown> | null
    children?: unknown
  }
  return ownChars(type, props) + drawnChars(children)
}

files.hooks/tracer/worktrees.ts:
/** The folders `git worktree list --porcelain` prints, the repository's own first: one `worktree <path>` line per block. */
export function parseWorktrees(listing: string): string[] {
  return listing
    .split('\n')
    .filter((line) => line.startsWith('worktree '))
    .map((line) => line.slice('worktree '.length))
}

/** The worktrees that are a helper's: git lists the project's own folder (or a folder above it) among them, and that one is the project. */
export const linkedRoots = (cwd: string, roots: readonly string[]): string[] =>
  roots.filter((root) => cwd !== root && !cwd.startsWith(`${root}/`))

/**
 * Whether a file at `path`, new to the records, may sit in a worktree git has not listed yet: it is in no listed
 * helper's worktree, and either outside the project or where Claude makes its helpers' worktrees inside it.
 */
export function mayBeInUnlistedWorktree(path: string, cwd: string, roots: readonly string[]): boolean {
  if (linkedRoots(cwd, roots).some((root) => path.startsWith(`${root}/`))) return false
  return !path.startsWith(`${cwd}/`) || path.startsWith(`${cwd}/.claude/worktrees/`)
}

files.hooks/tracer/summary.ts:
import type { RecordEntry } from '../../types'
import { countsOf } from './tree'

/** How many files the records hold, how many of them were changed, and the lines the changed ones gained and lost in all. */
export type Summary = { files: number; changed: number; added: number; removed: number }

/** The counts the pane's toolbar shows: every touched file, those whose Tag is not a plain Read, and the lines gained and lost over the session. A file whose lines the record cannot tell adds none. */
export function summaryOf(records: Record<string, RecordEntry>): Summary {
  const entries = Object.entries(records)
  const lines = entries.map(([path, e]) => countsOf(path, e))
  return {
    files: entries.length,
    changed: entries.filter(([, e]) => e.tag !== 'Read').length,
    added: lines.reduce((sum, c) => sum + (c?.added ?? 0), 0),
    removed: lines.reduce((sum, c) => sum + (c?.removed ?? 0), 0),
  }
}

/** The records whose Tag is not a plain Read: the files `Changed only` leaves in the tree. */
export const changedOf = (records: Record<string, RecordEntry>): Record<string, RecordEntry> =>
  Object.fromEntries(Object.entries(records).filter(([, e]) => e.tag !== 'Read'))

files.hooks/tracer/log.ts:
import type { LogEntry, RanEntry, TouchBy, TouchEntry } from '../../types'
import { endCut } from './paths'
import type { Touch } from './record'
import { countPair, diffCounts, type LineCounts } from './tree'

/** The longest text whose lines are counted: the same bound as the code view's, so a huge file costs no diff. */
const MAX_COUNTED_TEXT = 100_000

/** What the mod knows of a Touch's file besides the Touch: the text it has now where the mod read it, and the text the records held before the Touch. */
export type Known = { after: string | null; had: string | null }

/**
 * The lines a Touch added and removed: its text after against its text before. None for a Touch that changed nothing
 * (a Read) and for one whose before or after text the mod does not have. The text before is the Touch's own baseline,
 * else the text the records last held.
 */
export function countsOfTouch(touch: Touch, known: Known): LineCounts | null {
  if (touch.tag === 'Read') return null
  const [before, after] = [touch.baseline ?? known.had, touch.tag === 'Deleted' ? '' : (touch.seen ?? known.after)]
  if (before === null || after === null) return null
  return before.length > MAX_COUNTED_TEXT || after.length > MAX_COUNTED_TEXT ? null : diffCounts(before, after)
}

/** The most entries the log keeps, and the most Turns: the newest, so saved state stays far below the engine's size limit. */
const MAX_LOG = 2000

/**
 * The most entries the log's newest piece holds before they move into the older piece. Each write costs as much as
 * the piece it writes, so the newest piece stays small and the older one is written once for this many Touches.
 */
export const MAX_TAIL = 50

/** A Touch about to be logged: the entry without its number. */
export type NewTouch = Omit<TouchEntry, 'n' | 'type'>

/** The number of the last Touch among the entries, or null where there is none. */
export function lastNumber(entries: LogEntry[]): number | null {
  const last = entries.findLast((e): e is TouchEntry => e.type === 'touch')
  return last?.n ?? null
}

/** The entries with each Touch given the number after `base`, in session order; a Ran entry takes none. */
export function numbered(base: number, entries: Array<RanEntry | NewTouch>): LogEntry[] {
  let next = base
  return entries.map((e): LogEntry => {
    if ('type' in e) return e
    next += 1
    return { type: 'touch', n: next, ...e }
  })
}

/**
 * The older piece of the log with the newer piece after it. A write that stopped between the two pieces leaves the
 * newer piece's first entries in the older piece too; those are left out here, a Ran entry going with its Touches.
 */
function merged(older: LogEntry[], newer: LogEntry[]): LogEntry[] {
  const seen = lastNumber(older) ?? 0
  const first = newer.findIndex((e) => e.type === 'touch' && e.n > seen)
  if (first === -1) return older
  return [...older, ...newer.slice(newer[first - 1]?.type === 'ran' ? first - 1 : first)]
}

/** The log as the mod reads it: the older piece and the newer piece as one, the newest 2,000 entries. */
export const logOf = (older: LogEntry[], newer: LogEntry[]): LogEntry[] => merged(older, newer).slice(-MAX_LOG)

/** Runs the jobs it is given one after another, so two Touches raised together number and write the log one at a time. */
export function inOrder() {
  let last: Promise<unknown> = Promise.resolve()
  return <T>(job: () => Promise<T>): Promise<T> => {
    const run = last.then(job)
    last = run.catch(() => undefined)
    return run
  }
}

/** The Touches of one file, oldest first. A moved file's Touches include those at the places it moved from, back to before the move, and none of a later file at such a place. */
export function touchesOf(log: LogEntry[], path: string): TouchEntry[] {
  const found: TouchEntry[] = []
  let at = path
  for (const e of log.toReversed()) {
    if (e.type !== 'touch' || e.path !== at) continue
    found.unshift(e)
    at = e.oldPath ?? at
  }
  return found
}

/** Where the file of a Touch is now: its path, followed through the moves logged after the Touch. */
export function currentPath(log: LogEntry[], touch: TouchEntry): string {
  return log.reduce((at, e) => (e.type === 'touch' && e.n > touch.n && e.oldPath === at ? e.path : at), touch.path)
}

/** The first line of a text, such as a shell command or a prompt: what the log keeps of it. */
export const commandLine = (command: string): string => command.split(/\r?\n/)[0] ?? ''

/** A helper Claude started: its agent id, the type it was started as, and the description Claude gave it (empty when none). */
export type Helper = { id: string; type: string; description: string }

/** The most characters the By column holds. */
const MAX_BY = 40

/** The text cut to the most the By column holds, with an ellipsis where it was cut. */
const cutBy = (text: string): string => endCut(text, MAX_BY)

/** The name the Touches table gives who made a Touch: a helper by its description, else its type; a command by its text; the user as You. */
export function byText(by: TouchBy, helpers: Helper[]): string {
  if (by.kind === 'command') return cutBy(by.text)
  if (by.kind === 'user') return 'You'
  if (by.kind !== 'helper') return 'Claude'
  const helper = helpers.find((h) => h.id === by.id)
  if (helper === undefined) return 'Helper'
  return cutBy(helper.description.trim() === '' ? helper.type : helper.description)
}

/** The most characters of a prompt's first line a Turn keeps. */
const MAX_TURN_TEXT = 80

/** One Turn: its number, and the first line of the prompt that started it. */
export type Turn = { n: number; text: string }

/** The saved Turns with the default for a state that saved none: one Turn, before any prompt. */
const withTurns = (saved: Turn[] | undefined): Turn[] =>
  saved === undefined || saved.length === 0 ? [{ n: 1, text: '' }] : saved

/** The number of the Turn the session is in. */
export const currentTurn = (turns: Turn[]): number => withTurns(turns).at(-1)?.n ?? 1

/**
 * The Turns with a new one started by a prompt. The session's opening Turn, which has no prompt, is the first
 * prompt's own while nothing has been logged in it.
 */
export function startTurn(turns: Turn[], log: LogEntry[], prompt: string): Turn[] {
  const all = withTurns(turns)
  const last = all.at(-1) ?? { n: 1, text: '' }
  const text = commandLine(prompt).slice(0, MAX_TURN_TEXT)
  if (last.text === '' && !log.some((e) => e.turn === last.n)) return [...all.slice(0, -1), { n: last.n, text }]
  return [...all, { n: last.n + 1, text }].slice(-MAX_LOG)
}

/** The most rows the Touches table draws, the newest: the engine refuses a drawing of more than 20,000 elements, and the log holds up to 2,000 Touches. */
const MAX_TOUCH_ROWS = 200

/** The Touches the table draws, and how many earlier ones it leaves out. */
export const touchRowsOf = (touches: TouchEntry[]) => ({
  shown: touches.slice(-MAX_TOUCH_ROWS),
  earlier: Math.max(touches.length - MAX_TOUCH_ROWS, 0),
})

/** The Lines column's text for a Touch's counts: `+3 -1`, either part left out when zero; empty when there are none. */
export const linesText = (counts: LineCounts | null): string =>
  countPair(counts)
    .filter((part) => part !== '')
    .join(' ')

/** The characters of text the Touches table draws for these Touches, which count against the drawing's limit; the headings, labels and the line counting earlier Touches are a fixed allowance. */
export function tableChars(touches: TouchEntry[], helpers: Helper[]): number {
  const { shown } = touchRowsOf(touches)
  const rows = shown.map(
    (t) =>
      String(t.n).length +
      t.kind.length +
      byText(t.by, helpers).length +
      String(t.turn).length +
      linesText(t.counts).length,
  )
  return TABLE_ALLOWANCE + rows.reduce((sum, n) => sum + n, 0)
}

/** The characters of the table's heading, column labels and earlier-Touches line, with room to spare. */
const TABLE_ALLOWANCE = 100

